SELECT
    SUM(is_full)    AS fullCount,
    SUM(is_partial) AS partialCount,
    SUM(is_not)     AS notCount,
    SUM(status_0)   AS status0,
    SUM(status_1)   AS status1,
    SUM(status_3)   AS status3,
    SUM(status_4)   AS status4,
    SUM(status_5)   AS status5
FROM stat_sw_base_cache


        AND company_code IN
        #{c}


        AND county_code = #{countyCode}


        AND park_code = #{parkCode}


        AND yq_type = #{yqType}


        AND is_scqy = #{isScqy}
